//! Durable NodeExecutionEnv command semantics with streamed output, cancellation, and spill files.
use crate::{decode::StreamDecoder,errors::Failure,frame::{EVENT,Frame},sys};
use serde_json::{Map,Value,json};use parking_lot::Mutex;use std::{collections::HashSet,fs::{File,OpenOptions},io::{Read,Write},path::Path,process::{Child,Command,ExitStatus,Stdio},sync::mpsc::{Receiver,RecvTimeoutError,Sender},sync::Arc,thread,time::{Duration,Instant}};
const EXIT_STDIO_GRACE:Duration=Duration::from_millis(100);const READ_CHUNK:usize=64*1024;
pub type Groups=Arc<Mutex<HashSet<u32>>>;
pub enum Message{Data(usize,Vec<u8>),Eof(usize),Exit(ExitStatus),WaitFailed(String),Cancel,Kill}
pub struct ExecRequest{pub command:Option<String>,pub argv:Option<Vec<String>>,pub cwd:String,pub env:Map<String,Value>,pub inherit_env:bool,pub shell_path:Option<String>,pub timeout:Option<Duration>,pub spill:Option<(u64,u64)>}
impl ExecRequest{pub fn from_json(j:&Value)->Result<ExecRequest,Failure>{let strings=|v:&Value|->Option<Vec<String>>{v.as_array()?.iter().map(|x|x.as_str().map(str::to_owned)).collect()};Ok(ExecRequest{command:j["command"].as_str().map(str::to_owned),argv:strings(&j["argv"]),cwd:j["cwd"].as_str().ok_or_else(||Failure::new("EINVAL","exec needs cwd"))?.to_string(),env:j["env"].as_object().cloned().unwrap_or_default(),inherit_env:j["inheritEnv"].as_bool().unwrap_or(true),shell_path:j["shellPath"].as_str().map(str::to_owned),timeout:j["timeoutMs"].as_f64().map(|ms|Duration::from_secs_f64(ms/1000.0)),spill:j["spill"].as_object().and_then(|s|Some((s.get("afterBytes")?.as_u64()?,s.get("afterLines")?.as_u64()?)))})}}
pub fn kill_group(pid:u32){sys::kill_tree(pid)}
fn random_uuid()->String{let mut bytes=[0u8;16];if let Ok(mut random)=File::open("/dev/urandom"){let _=random.read_exact(&mut bytes);}bytes[6]=(bytes[6]&0x0f)|0x40;bytes[8]=(bytes[8]&0x3f)|0x80;let hex:String=bytes.iter().map(|b|format!("{b:02x}")).collect();format!("{}-{}-{}-{}-{}",&hex[0..8],&hex[8..12],&hex[12..16],&hex[16..20],&hex[20..32])}
struct Spill{after_bytes:u64,after_lines:u64,seen_bytes:u64,seen_newlines:u64,prefix:Vec<Vec<u8>>,file:Option<File>,path:Option<String>,failed:Option<String>}
impl Spill{fn push(&mut self,chunk:&[u8],tmpdir:&str){if self.failed.is_some()||chunk.is_empty(){return}if self.file.is_none(){self.seen_bytes+=chunk.len()as u64;self.seen_newlines+=chunk.iter().filter(|b|**b==b'\n').count()as u64;let lines=self.seen_newlines+u64::from(chunk.last()!=Some(&b'\n'));if self.seen_bytes<=self.after_bytes&&lines<=self.after_lines{self.prefix.push(chunk.to_vec());return}if let Err(e)=self.start(tmpdir){self.failed=Some(e);return}}if let Some(file)=&mut self.file{if let Err(e)=file.write_all(chunk){self.failed=Some(e.to_string())}}}fn start(&mut self,tmpdir:&str)->Result<(),String>{let dir=crate::fs::mkdtemp(&format!("{tmpdir}/tmp-")).map_err(|e|e.message)?;let dir=dir["path"].as_str().unwrap_or_default().to_string();let path=format!("{dir}/pi-output-{}.log",random_uuid());let mut file=OpenOptions::new().append(true).create(true).open(&path).map_err(|e|e.to_string())?;for chunk in self.prefix.drain(..){file.write_all(&chunk).map_err(|e|e.to_string())?}self.file=Some(file);self.path=Some(path);Ok(())}}
fn spawn_reader(stream:usize,mut pipe:impl Read+Send+'static,sender:Sender<Message>){thread::spawn(move||{let mut b=vec![0;READ_CHUNK];loop{match pipe.read(&mut b){Ok(0)|Err(_)=>break,Ok(n)=>if sender.send(Message::Data(stream,b[..n].to_vec())).is_err(){break}}}let _=sender.send(Message::Eof(stream));});}
fn spawn(request:&ExecRequest,program:&str,args:&[String],piped_stdin:bool)->std::io::Result<Child>{let mut c=Command::new(program);c.current_dir(&request.cwd).stdin(if piped_stdin{Stdio::piped()}else{Stdio::null()}).stdout(Stdio::piped()).stderr(Stdio::piped());sys::configure(&mut c,args,&request.env,request.inherit_env);let child=c.spawn()?;sys::after_spawn(&child);Ok(child)}
pub fn run(id:u32,request:ExecRequest,tmpdir:&str,out:&Sender<Frame>,messages:(Sender<Message>,Receiver<Message>),groups:&Groups)->Result<Value,Failure>{let(program,args,stdin_command)=match(&request.command,&request.argv){(Some(command),_)=>{let shell=sys::shell_config(request.shell_path.as_deref())?;let mut args=shell.args;if shell.command_on_stdin{(shell.program,args,Some(command.clone()))}else{args.push(command.clone());(shell.program,args,None)}},(None,Some(argv))=>match argv.split_first(){Some((first,rest))=>(first.clone(),rest.to_vec(),None),None=>return Err(Failure::new("spawn_error","Empty argv: no program to run"))},(None,None)=>return Err(Failure::new("EINVAL","exec needs command or argv"))};if !Path::new(&request.cwd).exists(){return Err(Failure::new("spawn_error",format!("Working directory does not exist: {}\nCannot execute bash commands.",request.cwd)))}let(sender,receiver)=messages;let mut child=spawn(&request,&program,&args,stdin_command.is_some()).map_err(|e|Failure::new("spawn_error",e.to_string()))?;if let(Some(command),Some(mut stdin))=(stdin_command,child.stdin.take()){let _=stdin.write_all(command.as_bytes());}let pid=child.id();groups.lock().insert(pid);let deadline=request.timeout.map(|t|Instant::now()+t);spawn_reader(0,child.stdout.take().unwrap(),sender.clone());spawn_reader(1,child.stderr.take().unwrap(),sender.clone());let waiter=sender.clone();thread::spawn(move||{let _=waiter.send(match child.wait(){Ok(s)=>Message::Exit(s),Err(e)=>Message::WaitFailed(e.to_string())});});drop(sender);let mut decoders=[StreamDecoder::new(),StreamDecoder::new()];let mut spill=request.spill.map(|(after_bytes,after_lines)|Spill{after_bytes,after_lines,seen_bytes:0,seen_newlines:0,prefix:Vec::new(),file:None,path:None,failed:None});let emit=|stream:usize,text:String|{if !text.is_empty(){let name=if stream==0{"stdout"}else{"stderr"};let _=out.send(Frame::with_payload(EVENT,id,json!({"kind":"output","stream":name}),text.into_bytes()));}};let mut ended=[false,false];let mut status:Option<Result<ExitStatus,String>>=None;let mut idle_until:Option<Instant>=None;let mut timed_out=false;let mut aborted=false;let mut killed=false;let kill=|killed:&mut bool|{if !*killed{*killed=true;kill_group(pid)}};loop{if status.is_some()&&ended[0]&&ended[1]{break}let now=Instant::now();let mut wait=Duration::from_secs(3600);if let Some(d)=deadline.filter(|_|!timed_out){wait=wait.min(d.saturating_duration_since(now))}if let Some(idle)=idle_until{wait=wait.min(idle.saturating_duration_since(now))}match receiver.recv_timeout(wait){Ok(Message::Data(stream,bytes))=>{emit(stream,decoders[stream].decode(&bytes,false));if let Some(s)=&mut spill{s.push(&bytes,tmpdir);if s.failed.is_some(){kill(&mut killed)}}if status.is_some(){idle_until=Some(Instant::now()+EXIT_STDIO_GRACE)}},Ok(Message::Eof(stream))=>ended[stream]=true,Ok(Message::Exit(exit))=>{status=Some(Ok(exit));idle_until=Some(Instant::now()+EXIT_STDIO_GRACE)},Ok(Message::WaitFailed(error))=>{status=Some(Err(error));idle_until=Some(Instant::now())},Ok(Message::Cancel)=>{aborted=true;kill(&mut killed)},Ok(Message::Kill)=>kill(&mut killed),Err(RecvTimeoutError::Timeout)=>{if deadline.is_some_and(|d|Instant::now()>=d)&&!timed_out&&status.is_none(){timed_out=true;kill(&mut killed)}else if idle_until.is_some_and(|t|Instant::now()>=t){break}},Err(RecvTimeoutError::Disconnected)=>break}}
 groups.lock().remove(&pid);emit(0,decoders[0].decode(&[],true));emit(1,decoders[1].decode(&[],true));let spill_path=spill.as_ref().and_then(|s|s.path.clone());let with_spill=|e:Failure|match &spill_path{Some(p)=>e.extra(json!({"spillPath":p})),None=>e};if timed_out{return Err(with_spill(Failure::new("timeout","timeout")))}if aborted{return Err(with_spill(Failure::new("aborted","aborted")))}if let Some(e)=spill.as_ref().and_then(|s|s.failed.clone()){return Err(Failure::new("unknown",format!("Failed to preserve complete shell output: {e}")))}let status=match status{Some(Ok(s))=>s,Some(Err(e))=>return Err(Failure::new("spawn_error",e)),None=>return Err(Failure::new("spawn_error","process did not report its exit"))};let mut result=json!({"exitCode":sys::exit_code(status)});if let Some(path)=spill_path{result["spillPath"]=json!(path)}Ok(result)}
